# -*- coding: utf-8 -*-
"""Generate a fully offline, single-file learning report. Python stdlib only."""
import argparse, json, html
from pathlib import Path
from learning_engine import load_curriculum, load_state, build_daily_plan, all_lessons

ROOT=Path(__file__).resolve().parents[1]
def esc(v): return html.escape(str(v),quote=True)
def build_page(curriculum,state,chart=None):
    plan=build_daily_plan(curriculum,state)
    lessons=all_lessons(curriculum)
    payload={"curriculum":curriculum,"state":state,"plan":plan,"lessons":lessons,"chart":chart}
    data=json.dumps(payload,ensure_ascii=False).replace("</","<\\/")
    title=esc(curriculum.get("title","A股技术分析学习系统"))
    return """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>"""+title+"""</title><style>
:root{font-family:system-ui,"Microsoft YaHei",sans-serif;color:#202633;background:#f4f6fa}*{box-sizing:border-box}body{margin:0}header{background:#18243a;color:white;padding:26px max(18px,calc((100% - 1120px)/2))}header h1{margin:0 0 8px;font-size:24px}header p{margin:0;color:#c8d2e2;font-size:13px}.wrap{max-width:1120px;margin:22px auto;padding:0 16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.card{background:white;border:1px solid #e2e7ef;border-radius:12px;padding:18px;margin-bottom:14px}.card h2{font-size:17px;margin:0 0 12px}.muted{color:#697586;font-size:13px}.pill{display:inline-block;border-radius:20px;background:#edf2fa;padding:3px 9px;font-size:12px;margin:2px}.chapter{border-top:1px solid #edf0f5;padding:12px 0}.lesson{display:flex;gap:10px;align-items:flex-start;padding:8px 0}.lesson button,.btn{border:1px solid #cbd5e1;background:#fff;border-radius:7px;padding:7px 11px;cursor:pointer;color:#24344d}.lesson button:hover,.btn:hover{background:#eef4ff}.primary{background:#2459a6;color:white;border-color:#2459a6}.progress{height:8px;background:#edf0f5;border-radius:8px;overflow:hidden}.progress i{display:block;height:100%;background:#3975c6}.quiz{padding:12px;background:#f7f9fc;border-radius:9px;margin:10px 0}.quiz label{display:block;padding:7px}.feedback{margin-top:8px;font-size:13px}.chartbox{overflow:auto}.chartbox svg{width:100%;min-width:520px;height:240px}.row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.small{font-size:12px}.footer{color:#697586;font-size:12px;padding:20px 0}.hide{display:none}textarea{width:100%;min-height:80px;border:1px solid #cbd5e1;border-radius:8px;padding:8px}
</style></head><body><header><h1>"""+title+"""</h1><p>以真实行情为教材 · 每日一图 · 每日一练 · 离线单文件</p></header><main class="wrap">
<section class="grid"><div class="card"><div class="muted">今日学习目标</div><h2 id="todayTitle">每日 18 分钟</h2><p id="todayDesc" class="muted">复习、学习新知识、观察图表并完成练习。</p></div><div class="card"><div class="muted">MVP课程掌握</div><h2 id="progressText">0%</h2><div class="progress"><i id="progressBar" style="width:0%"></i></div><p class="muted" id="progressMeta"></p></div><div class="card"><div class="muted">待复习</div><h2 id="dueCount">0 个知识点</h2><p class="muted">按答题表现自动安排复习间隔。</p></div></section>
<section class="card"><h2>今日学习</h2><div id="daily"></div></section>
<section class="card"><h2>每日一图 · 先观察，再看提示</h2><p class="muted" id="chartNote">如果由通达信分析流程生成了 chart_*.json，可在生成报告时传入；没有真实行情数据时，本页不会伪造K线。</p><div id="chart" class="chartbox"></div><div class="row"><button class="btn" id="revealChart">显示观察提示</button><span id="chartHint" class="muted hide">先描述价格方向、实体/影线和成交量变化，再判断是否有量价确认。单日形态不构成买卖信号。</span></div></section>
<section class="card"><h2>六大系统课程</h2><div id="curriculum"></div></section>
<section class="card"><h2>学习档案与数据迁移</h2><p class="muted">进度保存在本机浏览器；可导出 JSON 备份，也可在另一台设备导入。Python 运行时还可将进度保存到 state/learning_progress.json。</p><div class="row"><button class="btn primary" id="exportState">导出学习进度</button><label class="btn">导入学习进度<input id="importState" type="file" accept="application/json" hidden></label><button class="btn" id="resetState">清除此浏览器进度</button></div><p class="small muted" id="stateInfo"></p></section>
<div class="footer">本课程用于技术分析学习与研究训练，不构成投资建议。图表案例必须来自实际行情数据并标注数据截止日期；数据缺失时明确提示，不生成虚构行情。</div></main>
<script id="payload" type="application/json">"""+data+"""</script><script>
(function(){
const base=JSON.parse(document.getElementById('payload').textContent), KEY='tdx-learning-progress-v1';
let state=base.state||{schema_version:1,lesson_progress:{},reviews:[],daily_history:[]};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.schema_version===1)state=saved}catch(e){}
const lessons=base.lessons, byId=Object.fromEntries(lessons.map(x=>[x.id,x]));
function save(){localStorage.setItem(KEY,JSON.stringify(state));renderMeta()}
function progress(id){return state.lesson_progress[id]||{}}
function mastery(){const mvp=lessons.filter(x=>x.status==='mvp');return mvp.length?mvp.filter(x=>(progress(x.id).mastery||0)>=.8).length/mvp.length:0}
function renderMeta(){let p=mastery();document.getElementById('progressText').textContent=Math.round(p*100)+'%';document.getElementById('progressBar').style.width=(p*100)+'%';document.getElementById('progressMeta').textContent='已掌握 '+Math.round(p*lessons.filter(x=>x.status==='mvp').length)+' / '+lessons.filter(x=>x.status==='mvp').length+' 个MVP知识点';let due=Object.values(state.lesson_progress).filter(x=>x.due_date&&x.due_date<=new Date().toISOString().slice(0,10)).length;document.getElementById('dueCount').textContent=due+' 个知识点';document.getElementById('stateInfo').textContent='最近更新：'+(state.updated_at||'尚未记录')+'；浏览器本地保存'+(localStorage.getItem(KEY)?'已启用':'尚未写入')}
function renderDaily(){let due=Object.entries(state.lesson_progress).filter(([id,p])=>p.due_date&&p.due_date<=new Date().toISOString().slice(0,10)).slice(0,3);let next=lessons.find(x=>x.status==='mvp'&&(progress(x.id).mastery||0)<.8);let box=document.getElementById('daily');box.innerHTML='<p><b>到期复习：</b>'+(due.length?due.map(([id])=>byId[id]?.title||id).join('、'):'今天没有到期复习')+'</p><p><b>新知识：</b>'+(next?next.title:'MVP课程已达到掌握标准，可进行综合练习')+'</p><p><b>每日一练：</b>完成所选知识点的3道自测题，并给自己的解释质量打分。</p>';document.getElementById('todayTitle').textContent='今日约 '+base.plan.minutes+' 分钟';document.getElementById('todayDesc').textContent='复习 '+due.length+' 项 · 新知识 '+(next?'1项':'0项')+' · 每日一图 1 项 · 每日一练 3题'}
function renderCurriculum(){let root=document.getElementById('curriculum');root.innerHTML='';base.curriculum.chapters.forEach(ch=>{let d=document.createElement('div');d.className='chapter';d.innerHTML='<h3>'+ch.id+' · '+ch.title+' <span class="pill">'+(ch.status==='mvp'?'首期完整教学':'课程目录已建立')+'</span></h3><p class="muted">'+ch.goal+'</p>';ch.lessons.forEach(row=>{let id=row[0],p=progress(id),l=document.createElement('div');l.className='lesson';let b=document.createElement('button');b.textContent=(p.mastery>=.8?'已掌握 · ':'学习 · ')+row[1];b.onclick=()=>openLesson(id);let info=document.createElement('span');info.className='muted small';info.textContent=id+' · '+Math.round((p.mastery||0)*100)+'%';l.append(b,info);d.append(l)});root.append(d)})}
function openLesson(id){let l=byId[id];if(!l)return;let old=document.getElementById('lessonModal');if(old)old.remove();let box=document.createElement('section');box.id='lessonModal';box.className='card';box.innerHTML='<h2>'+l.id+' · '+l.title+'</h2><p><b>学习目标：</b>'+l.objective+'</p><p><b>前置知识：</b>'+l.prerequisite+'</p><p><b>核心讲解：</b>'+l.teaching+'</p><div class="quiz"><b>自测 1：K线实体表示什么？</b><label><input type="radio" name="q1" value="a"> 开盘价与收盘价之间的区间</label><label><input type="radio" name="q1" value="b"> 最高价与最低价之间的区间</label><label><input type="radio" name="q1" value="c"> 当日成交量</label></div><div class="quiz"><b>自测 2：量比通常如何计算？</b><label><input type="radio" name="q2" value="a"> 当前成交量 ÷ 参照期平均成交量</label><label><input type="radio" name="q2" value="b"> 当前价格 ÷ 均线价格</label><label><input type="radio" name="q2" value="c"> 成交额 ÷ 换手率</label></div><div class="quiz"><b>自测 3：哪种分析方法更可靠？</b><label><input type="radio" name="q3" value="a"> 单凭一个形态预测涨跌</label><label><input type="radio" name="q3" value="b"> 先描述事实，再结合位置、周期和后续确认</label><label><input type="radio" name="q3" value="c"> 忽略数据口径和成交量</label></div><div class="feedback" id="quizFeedback"></div><p>解释质量：<select id="quality"><option value="2">2 - 只记住结论</option><option value="3" selected>3 - 能解释概念</option><option value="4">4 - 能结合图表说明</option><option value="5">5 - 能指出局限与反例</option></select></p><div class="row"><button class="btn primary" id="submitLesson">记录学习结果</button><button class="btn" onclick="document.getElementById('lessonModal').remove()">关闭</button></div>';document.querySelector('main').insertBefore(box,document.querySelector('main').children[1]);box.scrollIntoView({behavior:'smooth'});box.querySelectorAll('input[type=radio]').forEach(x=>x.onchange=()=>{document.getElementById('quizFeedback').textContent='已选择答案。完成三题后提交，系统将按正确题数计算掌握度。'});document.getElementById('submitLesson').onclick=()=>{let answers={q1:'a',q2:'a',q3:'b'},correct=Object.keys(answers).filter(k=>box.querySelector('input[name='+k+']:checked')?.value===answers[k]).length;let total=3,quality=Number(document.getElementById('quality').value),p=progress(id);p.attempts=(p.attempts||0)+1;p.last_accuracy=correct/total;p.mastery=Math.min(1,.65*(p.mastery||0)+.25*p.last_accuracy+.10*quality/5);p.interval_days=correct/total>=.9&&quality>=4?Math.min(30,(p.interval_days||0)*2||1):correct/total>=.7?Math.max(1,p.interval_days||1):1;p.last_seen=new Date().toISOString().slice(0,10);let due=new Date();due.setDate(due.getDate()+p.interval_days);p.due_date=due.toISOString().slice(0,10);state.lesson_progress[id]=p;state.reviews.push({date:p.last_seen,lesson_id:id,correct,total,quality,mastery:p.mastery});save();renderDaily();renderCurriculum();box.remove();}}
function renderChart(){let c=base.chart;if(!c||!c.dates||!c.ohlc){document.getElementById('chart').innerHTML='<p class="muted">尚未载入真实行情案例。运行原有 run_analysis.py 生成 chart_*.json，再用 learning_report.py --chart 指定该文件即可。此处不展示虚构K线。</p>';return}let w=900,h=230,step=(w-50)/c.dates.length,vals=c.ohlc.flatMap(x=>[x[2],x[3]]),min=Math.min(...vals),max=Math.max(...vals),scale=y=>h-20-(y-min)/(max-min||1)*(h-40),s='<svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="真实行情K线图">';c.ohlc.forEach((x,i)=>{let xx=35+i*step+step/2,up=x[1]>=x[0],col=up?'#cf3d36':'#16865b',y1=scale(x[3]),y2=scale(x[2]),yo=scale(x[0]),yc=scale(x[1]),top=Math.min(yo,yc),bh=Math.max(1,Math.abs(yc-yo));s+='<line x1="'+xx+'" y1="'+y1+'" x2="'+xx+'" y2="'+y2+'" stroke="'+col+'"/><rect x="'+(xx-step*.28)+'" y="'+top+'" width="'+(step*.56)+'" height="'+bh+'" fill="'+col+'"/>'});s+='</svg>';document.getElementById('chart').innerHTML=s;document.getElementById('chartNote').textContent='真实行情案例：'+c.dates.length+'根K线。具体日期与数据截止日期以原始分析 JSON 为准。'}
document.getElementById('revealChart').onclick=()=>document.getElementById('chartHint').classList.toggle('hide');
document.getElementById('exportState').onclick=()=>{let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='learning_progress.json';a.click();URL.revokeObjectURL(a.href)};
document.getElementById('importState').onchange=e=>{let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(x.schema_version!==1||!x.lesson_progress)throw Error('版本不匹配');state=x;save();renderDaily();renderCurriculum();alert('学习进度导入成功')}catch(err){alert('导入失败：'+err.message)}};r.readAsText(f)};
document.getElementById('resetState').onclick=()=>{if(confirm('仅清除此浏览器保存的进度？请先导出备份。')){localStorage.removeItem(KEY);state={schema_version:1,lesson_progress:{},reviews:[],daily_history:[]};renderDaily();renderCurriculum();renderMeta()}};
renderDaily();renderMeta();renderCurriculum();renderChart();
})();
</script></body></html>"""
def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--state",default=str(ROOT/"state"/"learning_progress.json"))
    ap.add_argument("--chart",default=None,help="optional chart_*.json generated by analyze.py")
    ap.add_argument("--out",default="learning_report.html")
    a=ap.parse_args()
    c=load_curriculum(); s=load_state(a.state); chart=json.loads(Path(a.chart).read_text(encoding="utf-8")) if a.chart else None
    Path(a.out).write_text(build_page(c,s,chart),encoding="utf-8")
    print("LEARNING_REPORT_OK",Path(a.out).resolve())
if __name__=="__main__": main()
